import {
  IGpx,
  IGpxCopyright,
  IGpxEmail,
  IGpxLink,
  IGpxMetadata,
  IGpxPerson,
  IGpxRte,
  IGpxTrk,
  IGpxTrkseg,
  IGpxWpt,
} from '../@types/gpx.types';

const injectNodeValueIfExist = <T extends {}>(
  obj: T,
  key: keyof T,
  parent: Element,
  options: {
    tagName?: string;
    parseFunc?: (str: string) => T[keyof T];
  } = {},
) => {
  const opts = {
    parseFunc: (s: string) => s as T[keyof T],
    ...options,
  };

  const tagName = opts?.tagName ?? (key as string);
  const nodes = parent.getElementsByTagName(tagName);
  if (nodes.length) obj[key] = opts.parseFunc(nodes[0].textContent ?? '');
};

const parseGpxLink = (linkElement: Element): IGpxLink => {
  const link: IGpxLink = {
    href: linkElement.getAttribute('href') ?? '',
  };

  injectNodeValueIfExist<IGpxLink>(link, 'text', linkElement);
  injectNodeValueIfExist<IGpxLink>(link, 'type', linkElement);

  return link;
};

const parseGpxCopyright = (el: Element): IGpxCopyright => {
  const data: IGpxCopyright = {
    author: el.getAttribute('author') ?? '',
  };

  injectNodeValueIfExist<IGpxCopyright>(data, 'license', el);
  injectNodeValueIfExist<IGpxCopyright>(data, 'year', el, { parseFunc: parseInt });

  return data;
};

const parseGpxEmail = (emailElement: Element): IGpxEmail => {
  return {
    id: emailElement.getAttribute('id') ?? '',
    domain: emailElement.getAttribute('domain') ?? '',
  };
};
const parseGpxRte = (rteElement: Element): IGpxRte => {
  const rte: IGpxRte = {
    rtept: Array.from(rteElement.getElementsByTagName('rtept')).map(parseGpxWpt),
  };

  // <name> xsd:string </name> [0..1] ?
  injectNodeValueIfExist<IGpxRte>(rte, 'name', rteElement);

  // <cmt> xsd:string </cmt> [0..1] ?
  injectNodeValueIfExist<IGpxRte>(rte, 'comment', rteElement, { tagName: 'cmt' });

  // <desc> xsd:string </desc> [0..1] ?
  injectNodeValueIfExist<IGpxRte>(rte, 'description', rteElement, { tagName: 'desc' });

  // <src> xsd:string </src> [0..1] ?
  injectNodeValueIfExist<IGpxRte>(rte, 'src', rteElement);

  // <link> linkType </link> [0..*] ?
  const linkNodes = rteElement.getElementsByTagName('link');
  if (linkNodes.length) rte.link = Array.from(linkNodes).map(parseGpxLink);

  // <number> xsd:nonNegativeInteger </number> [0..1] ?
  injectNodeValueIfExist<IGpxRte>(rte, 'number', rteElement, { parseFunc: parseInt });

  // <type> xsd:string </type> [0..1] ?
  injectNodeValueIfExist<IGpxRte>(rte, 'type', rteElement);

  // <extensions> extensionsType </extensions> [0..1] ?
  const extensionsNodes = rteElement.getElementsByTagName('extensions');
  if (extensionsNodes.length) rte.extensions = extensionsNodes[0].textContent ?? '';

  return rte;
};

const parseGpxPerson = (el: Element): IGpxPerson => {
  const data: IGpxPerson = {};
  //<name> xsd:string </name> [0..1] ?
  const nameNodes = el.getElementsByTagName('name');
  if (nameNodes.length) data.name = nameNodes[0].textContent ?? '';

  //<email> emailType </email> [0..1] ?
  const emailNodes = el.getElementsByTagName('email');
  if (emailNodes.length) data.email = parseGpxEmail(emailNodes[0]);

  //<link> linkType </link> [0..1] ?
  const linkNodes = el.getElementsByTagName('link');
  if (linkNodes.length) data.link = parseGpxLink(linkNodes[0]);

  return data;
};

const parseGpxMetadata = (metadataEl: Element): IGpxMetadata => {
  const metadata: IGpxMetadata = {};
  // <name> xsd:string </name> [0..1] ?
  const nameNodes = metadataEl.getElementsByTagName('name');
  if (nameNodes.length) metadata.name = nameNodes[0].textContent ?? '';

  // <desc> xsd:string </desc> [0..1] ?
  const descNodes = metadataEl.getElementsByTagName('desc');
  if (descNodes.length) metadata.desc = descNodes[0].textContent ?? '';

  // <author> personType </author> [0..1] ?
  const authorNodes = metadataEl.getElementsByTagName('author');
  if (authorNodes.length) metadata.author = parseGpxPerson(authorNodes[0]);

  // <copyright> copyrightType </copyright> [0..1] ?
  const copyrightNodes = metadataEl.getElementsByTagName('copyright');
  if (copyrightNodes.length) metadata.copyright = parseGpxCopyright(copyrightNodes[0]);

  // <link> linkType </link> [0..*] ?
  const linkNodes = metadataEl.getElementsByTagName('link');
  if (linkNodes.length) metadata.link = Array.from(linkNodes).map(parseGpxLink);

  // <time> xsd:dateTime </time> [0..1] ?
  const timeNodes = metadataEl.getElementsByTagName('time');
  if (timeNodes.length) metadata.time = timeNodes[0].textContent ?? '';

  // <keywords> xsd:string </keywords> [0..1] ?
  const keywordsNodes = metadataEl.getElementsByTagName('keywords');
  if (keywordsNodes.length) metadata.keywords = keywordsNodes[0].textContent ?? '';

  // <bounds> boundsType </bounds> [0..1] ?
  const boundsNodes = metadataEl.getElementsByTagName('bounds');
  if (boundsNodes.length) {
    metadata.bounds = {
      minlat: parseInt(boundsNodes[0].getAttribute('minlat') ?? ''),
      minlon: parseInt(boundsNodes[0].getAttribute('minlon') ?? ''),
      maxlat: parseInt(boundsNodes[0].getAttribute('maxlat') ?? ''),
      maxlon: parseInt(boundsNodes[0].getAttribute('maxlon') ?? ''),
    };
  }

  // <extensions> extensionsType </extensions> [0..1] ?
  const extensionsNodes = metadataEl.getElementsByTagName('extensions');
  if (extensionsNodes.length) metadata.extensions = extensionsNodes[0].textContent ?? '';

  return metadata;
};

const parseGpxTrkseg = (trksegEl: Element): IGpxTrkseg => {
  return {
    trkpt: Array.from(trksegEl.getElementsByTagName('trkpt')).map(parseGpxWpt),
  };
};

const parseGpxTrk = (trkElement: Element): IGpxTrk => {
  const trk: IGpxTrk = {
    trkseg: Array.from(trkElement.getElementsByTagName('trkseg')).map(parseGpxTrkseg),
  };

  // <name> xsd:string </name> [0..1] ?
  const nameNodes = trkElement.getElementsByTagName('name');
  if (nameNodes.length) trk.name = nameNodes[0].textContent ?? '';

  // <cmt> xsd:string </cmt> [0..1] ?
  const cmtNodes = trkElement.getElementsByTagName('cmt');
  if (cmtNodes.length) trk.comment = cmtNodes[0].textContent ?? '';

  // <desc> xsd:string </desc> [0..1] ?
  const descNodes = trkElement.getElementsByTagName('desc');
  if (descNodes.length) trk.description = descNodes[0].textContent ?? '';

  // <src> xsd:string </src> [0..1] ?
  const srcNodes = trkElement.getElementsByTagName('src');
  if (srcNodes.length) trk.src = srcNodes[0].textContent ?? '';

  // <link> linkType </link> [0..*] ?
  const linkNodes = trkElement.getElementsByTagName('link');
  if (linkNodes.length) trk.link = Array.from(linkNodes).map(parseGpxLink);

  // <number> xsd:nonNegativeInteger </number> [0..1] ?
  const numberNodes = trkElement.getElementsByTagName('number');
  if (numberNodes.length) trk.number = parseInt(numberNodes[0].textContent ?? '');

  // <type> xsd:string </type> [0..1] ?
  const typeNodes = trkElement.getElementsByTagName('type');
  if (typeNodes.length) trk.type = typeNodes[0].textContent ?? '';

  // <extensions> extensionsType </extensions> [0..1] ?
  const extensionsNodes = trkElement.getElementsByTagName('extensions');
  if (extensionsNodes.length) trk.extensions = extensionsNodes[0].textContent ?? '';

  return trk;
};

const parseGpxWpt = (wpt: Element) => {
  const lat = parseFloat(wpt.getAttribute('lat') ?? '');
  const lon = parseFloat(wpt.getAttribute('lon') ?? '');

  const wptData: IGpxWpt = {
    lat,
    lon,
  };

  //<ele> xsd:decimal </ele> [0..1] ?
  const eleNode = wpt.getElementsByTagName('ele');
  if (eleNode.length) wptData.ele = parseFloat(eleNode[0].textContent ?? '');

  //<time> xsd:dateTime </time> [0..1] ?
  const timeNode = wpt.getElementsByTagName('time');
  if (timeNode.length) wptData.time = timeNode[0].textContent ?? '';

  //<magvar> degreesType </magvar> [0..1] ?
  const magvarNode = wpt.getElementsByTagName('magvar');
  if (magvarNode.length) wptData.magvar = parseFloat(magvarNode[0].textContent ?? '');

  //<geoidheight> xsd:decimal </geoidheight> [0..1] ?
  const geoidheightNode = wpt.getElementsByTagName('geoidheight');
  if (geoidheightNode.length)
    wptData.geoidheight = parseFloat(geoidheightNode[0].textContent ?? '');

  //<name> xsd:string </name> [0..1] ?
  const nameNode = wpt.getElementsByTagName('name');
  if (nameNode.length) wptData.name = nameNode[0].textContent ?? '';

  //<cmt> xsd:string </cmt> [0..1] ?
  const cmtNode = wpt.getElementsByTagName('cmt');
  if (cmtNode.length) wptData.comment = cmtNode[0].textContent ?? '';

  //<desc> xsd:string </desc> [0..1] ?
  const descNode = wpt.getElementsByTagName('desc');
  if (descNode.length) wptData.description = descNode[0].textContent ?? '';

  //<src> xsd:string </src> [0..1] ?
  const srcNode = wpt.getElementsByTagName('src');
  if (srcNode.length) wptData.src = srcNode[0].textContent ?? '';

  //<link> linkType </link> [0..*] ?
  const linkNode = wpt.getElementsByTagName('link');
  if (linkNode.length) wptData.link = Array.from(linkNode).map(parseGpxLink);

  //<sym> xsd:string </sym> [0..1] ?
  const symNode = wpt.getElementsByTagName('sym');
  if (symNode.length) wptData.sym = symNode[0].textContent ?? '';

  //<type> xsd:string </type> [0..1] ?
  const typeNode = wpt.getElementsByTagName('type');
  if (typeNode.length) wptData.type = typeNode[0].textContent ?? '';

  //<fix> fixType </fix> [0..1] ?
  const fixNode = wpt.getElementsByTagName('fix');
  if (fixNode.length) wptData.fix = (fixNode[0].textContent ?? 'none') as IGpxWpt['fix'];

  //<sat> xsd:nonNegativeInteger </sat> [0..1] ?
  const satNode = wpt.getElementsByTagName('sat');
  if (satNode.length) wptData.sat = parseInt(satNode[0].textContent ?? '');

  //<hdop> xsd:decimal </hdop> [0..1] ?
  const hdopNode = wpt.getElementsByTagName('hdop');
  if (hdopNode.length) wptData.hdop = parseFloat(hdopNode[0].textContent ?? '');

  //<vdop> xsd:decimal </vdop> [0..1] ?
  const vdopNode = wpt.getElementsByTagName('vdop');
  if (vdopNode.length) wptData.vdop = parseFloat(vdopNode[0].textContent ?? '');

  //<pdop> xsd:decimal </pdop> [0..1] ?
  const pdopNode = wpt.getElementsByTagName('pdop');
  if (pdopNode.length) wptData.pdop = parseFloat(pdopNode[0].textContent ?? '');

  //<ageofdgpsdata> xsd:decimal </ageofdgpsdata> [0..1] ?
  const ageofdgpsdataNode = wpt.getElementsByTagName('ageofdgpsdata');
  if (ageofdgpsdataNode.length)
    wptData.ageofdgpsdata = parseFloat(ageofdgpsdataNode[0].textContent ?? '');

  //<dgpsid> dgpsStationType </dgpsid> [0..1] ?
  const dgpsidNode = wpt.getElementsByTagName('dgpsid');
  if (dgpsidNode.length) wptData.dgpsid = parseInt(dgpsidNode[0].textContent ?? '');

  //<extensions> extensionsType </extensions> [0..1] ?
  const extensionsNode = wpt.getElementsByTagName('extensions');
  if (extensionsNode.length) wptData.extensions = extensionsNode[0].textContent ?? '';

  const atempEls = wpt.getElementsByTagNameNS('*', 'atemp');
  if (atempEls.length) wptData.atemp = parseFloat(atempEls[0].textContent ?? '');

  const hrEls = wpt.getElementsByTagNameNS('*', 'hr');
  if (hrEls.length) wptData.hr = parseInt(hrEls[0].textContent ?? '');

  return wptData;
};

export const parseStringAsGPX = (gpxString: string): IGpx => {
  const parser = new DOMParser();
  const dom = parser.parseFromString(gpxString, 'application/xml');
  if (dom.documentElement.nodeName == 'parsererror') throw new Error('error while parsing ');

  const gpxNode = dom.getElementsByTagName('gpx')[0];
  const data: IGpx = {
    creator: gpxNode.getAttribute('creator') ?? 'pohodnik.tk',
    wpt: Array.from(dom.getElementsByTagName('wpt')).map(parseGpxWpt),
    rte: Array.from(dom.getElementsByTagName('rte')).map(parseGpxRte),
    trk: Array.from(dom.getElementsByTagName('trk')).map(parseGpxTrk),
  };

  const metadataNode = gpxNode.getElementsByTagName('metadata');
  if (metadataNode.length) data.metadata = parseGpxMetadata(metadataNode[0]);

  return data;
};
